    "exportPrompt": "Ich übertrage meinen Kontext zu einem anderen Assistenten. Exportiere die Erinnerungen und Vorlieben, auf die du über mich zugreifen kannst, als einfache Markdown-Liste mit einer Tatsache pro Eintrag. Nimm meine Antwortvorlieben, wiederkehrende Projekte, Werkzeuge und dauerhaften persönlichen Kontext auf. Behalte Datumsangaben bei, wenn sie bekannt sind. Lass Passwörter, Tokens, Finanzkennungen und andere Geheimnisse weg. Unterscheide bestätigte Tatsachen von Unsicherem und sag, falls der Export unvollständig sein könnte.",
